ROOT=Path(os.environ.get('SOURCE_ROOT','.')).resolve(); OUT=Path(os.environ.get('OUTPUT_DIR',str(Path(__file__).resolve().parent))).resolve(); OUT.mkdir(parents=True,exist_ok=True)
