def ev(file,needle):
 lines=(ROOT/file).read_text().splitlines(); matches=[i for i,x in enumerate(lines) if needle in x]; assert matches,(file,needle)
 n=matches[0]+1
 return {'file':file,'line':n,'quote':lines[n-1].strip(),'url':f'https://github.com/VanDalkvist/durable-zero/blob/{SHA}/{file}#L{n}'}
